def bfs(graph, start, end):
    que = [start]
    visited = [False] * (start + 1)

    while que:
        u = que.pop(0)
        visited[u] = True
        for v in range(len(graph)):
            if not visited[v] and graph[u][v]:
                    que.append(v)
                    visited[v] = True


def dfs(graph, start, end):
    seen = set()
    u = start
    while u != end:
        seen.add(u)
        u = (u, start) in graph and not in seen
            if u is None or u in seen:
                break
            v = graph[u]
            while v is not None:
                        seen.add(v)
                    v = graph[v]
                    break
        ans1 = False
        if u == end:
            ans1 = True
    return ans1


def is_path_exists(graph, start, end):
    stack = (start, start)
    while stack:
        u, v = stack.pop()
        if u == end:
            return (None, None)
        stack.append((u, v))
    return (False, None)


